window.kbPageData["views/entry/k-f089608e006a6a61"] = {"key":"entry/k-f089608e006a6a61","state":{"route":"entry/k-f089608e006a6a61"},"node":{"id":"k-f089608e006a6a61","mode":"k","title":"动植物品种及其生产方法的专利规则","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["动植物品种及其生产方法的专利客体规则"],"qs":["国考 2024 行政执法 行测#15"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"动物和植物品种本身不授予专利权。其生产方法符合专利法规定的，可以授予专利权。","review":{"definition":"动物和植物品种本身不授予专利权。其生产方法符合专利法规定的，可以授予专利权。","explanation":"D项描述的是针对水稻的辐射诱变育种技术，判断时应区分育种方法与所得水稻品种。题目问哪一项不能被授予专利权，B项治疗主动脉夹层的手术方法属于疾病治疗方法，落入法定排除范围。D项的具体技术能否获权仍取决于其是否满足相应条件。","references":[],"evidence":"对前款第（四）项所列产品的生产方法，可以依照本法规定授予专利权","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2024 行政执法 行测#15":{"paper":"国考 2024 行政执法 行测","n":15,"mod":"常识判断","src":["dfddc59dc6e7d9da5d71.pdf",3],"asrc":["6493f3a6a55c38431852.pdf",5],"card":"373d3c8b70e80f36d9d3207c","links":[{"id":"k-f089608e006a6a61","role":"解题依据","why":"动植物品种属于排除客体，其生产方法可依专利法获权，据此判断水稻育种技术的客体资格。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-f089608e006a6a61":[["国考 2024 行政执法 行测#15"]]}};
